package org.ofdrw.converter.font;

import org.junit.jupiter.api.Test;
import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.assertThrows;

public class TrueTypeFontParseTests {

    @Test
    public void parseThrowsOnMissingMaxp() throws IOException {
        byte[] data = buildBytesMissingMaxp();
        TTFDataStream raf = new ByteArrayTTFDataStream(data);
        TrueTypeFont font = new TrueTypeFont();
        // Expect IllegalArgumentException when head is present but maxp is missing
        assertThrows(IllegalArgumentException.class, () -> font.parse(raf));
    }

    // Builds a TT font-like byte sequence with:
    // - non-Type1 version
    // - one table: head at offset 128
    // - head present, but maxp table is absent -> should throw IllegalArgumentException
    private byte[] buildBytesMissingMaxp() {
        int headOffset = 128;
        byte[] bytes = new byte[headOffset + 64]; // 192 bytes total
        int idx = 0;

        // version (4 bytes) - non-Type1
        bytes[idx++] = 0; bytes[idx++] = 0; bytes[idx++] = 0; bytes[idx++] = 0;

        // numberOfTables (2) and following header fields (searchRange, entrySelector, rangeShift)
        bytes[idx++] = 0; bytes[idx++] = 1; // numberOfTables = 1
        bytes[idx++] = 0; bytes[idx++] = 0; // searchRange
        bytes[idx++] = 0; bytes[idx++] = 0; // entrySelector
        bytes[idx++] = 0; bytes[idx++] = 0; // rangeShift

        // Table directory entry for "head"
        bytes[idx++] = 'h'; bytes[idx++] = 'e'; bytes[idx++] = 'a'; bytes[idx++] = 'd';
        // 9: checksum (4 bytes)
        bytes[idx++] = 0; bytes[idx++] = 0; bytes[idx++] = 0; bytes[idx++] = 0;
        //  offset (4 bytes) - head at 128
        bytes[idx++] = 0; bytes[idx++] = 0; bytes[idx++] = 0; bytes[idx++] = (byte) 0x80;
        //  length (4 bytes) - 64 bytes
        bytes[idx++] = 0; bytes[idx++] = 0; bytes[idx++] = 0; bytes[idx++] = 0x40;

        // pad to headOffset (128)
        for (int i = idx; i < headOffset; i++) {
            bytes[i] = 0;
        }

        // head table content:
        // place unitsPerEm at headOffset + 18 (2 bytes), indexToLocFormat at headOffset + 50 (2 bytes)
        // unitsPerEm = 100 (0x0064)
        bytes[headOffset + 18] = 0;
        bytes[headOffset + 19] = 100;
        // indexToLocFormat = 0
        bytes[headOffset + 50] = 0;
        bytes[headOffset + 51] = 0;

        return bytes;
    }

    // Minimal ByteArray-backed TTF data stream to drive the parse() under test
    private static class ByteArrayTTFDataStream extends TTFDataStream {
        private final byte[] data;
        private int pos = 0;

        ByteArrayTTFDataStream(byte[] data) {
            this.data = data;
        }

        @Override
        public int read() throws IOException {
            if (pos >= data.length) return -1;
            return data[pos++] & 0xFF;
        }

        @Override
        public int read(byte[] b, int off, int len) throws IOException {
            if (pos >= data.length) return -1;
            int remaining = data.length - pos;
            int toRead = Math.min(len, remaining);
            System.arraycopy(data, pos, b, off, toRead);
            pos += toRead;
            return toRead;
        }

        @Override
        public long readLong() throws IOException {
            long val = 0;
            for (int i = 0; i < 8; i++) {
                int ch = read();
                if (ch == -1) throw new IOException("EOF");
                val = (val << 8) | (ch & 0xFF);
            }
            return val;
        }

        @Override
        public int readUnsignedShort() throws IOException {
            int b1 = read();
            int b2 = read();
            if (b1 == -1 || b2 == -1) throw new IOException("EOF");
            return ((b1 & 0xFF) << 8) | (b2 & 0xFF);
        }

        @Override
        public long readUnsignedInt() throws IOException {
            long b1 = read();
            long b2 = read();
            long b3 = read();
            long b4 = read();
            if (b4 == -1) throw new IOException("EOF");
            return ((b1 & 0xFF) << 24) | ((b2 & 0xFF) << 16) | ((b3 & 0xFF) << 8) | (b4 & 0xFF);
        }

        @Override
        public short readSignedShort() throws IOException {
            int b1 = read();
            int b2 = read();
            if (b2 == -1) throw new IOException("EOF");
            int v = ((b1 & 0xFF) << 8) | (b2 & 0xFF);
            return (short) v;
        }

        @Override
        public String readString(int length) throws IOException {
            byte[] buf = new byte[length];
            int r = read(buf, 0, length);
            if (r != length) throw new IOException("short read");
            return new String(buf, StandardCharsets.ISO_8859_1);
        }

        @Override
        public String readString(int length, String charset) throws IOException {
            byte[] buf = new byte[length];
            int r = read(buf, 0, length);
            if (r != length) throw new IOException("short read");
            return new String(buf, charset);
        }

        @Override
        public String readString(int length, java.nio.charset.Charset charset) throws IOException {
            byte[] buf = new byte[length];
            int r = read(buf, 0, length);
            if (r != length) throw new IOException("short read");
            return new String(buf, charset);
        }

        @Override
        public void seek(long pos) throws IOException {
            this.pos = (int) pos;
        }

        @Override
        public long getCurrentPosition() throws IOException {
            return pos;
        }

        @Override
        public InputStream getOriginalData() throws IOException {
            return new ByteArrayInputStream(data);
        }

        @Override
        public long getOriginalDataSize() {
            return data.length;
        }

        @Override
        public void close() throws IOException {
            // no resources to release
        }
    }
}

