        putTable(buffer, 28, "maxp", 154, 6);
        putTable(buffer, 44, "loca", 160, 10);
        putTable(buffer, 60, "glyf", 170, 1);

        buffer.putShort(118, (short) 1000);
        buffer.putShort(150, (short) 0);

        buffer.putShort(158, (short) 4);

        buffer.putShort(160, (short) 0);
        buffer.putShort(162, (short) 1);
        buffer.putShort(164, (short) 3);
        buffer.putShort(166, (short) 3);
        buffer.putShort(168, (short) 5);

        return data;
    }

    private static byte[] fontWithHeadOnly() {
        byte[] data = new byte[154];
        ByteBuffer buffer = ByteBuffer.wrap(data).order(ByteOrder.BIG_ENDIAN);

        buffer.putInt(0, 0x00010000);
        buffer.putShort(4, (short) 1);
        putTable(buffer, 12, "head", 100, 54);
        buffer.putShort(118, (short) 1000);
        buffer.putShort(150, (short) 0);

        return data;
    }

    private static void putTable(
            ByteBuffer buffer, int directoryOffset, String tag, int offset, int length) {
        byte[] tagBytes = tag.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
        buffer.position(directoryOffset);
        buffer.put(tagBytes);
        buffer.putInt(0);
        buffer.putInt(offset);
        buffer.putInt(length);
    }
