    }

    private static void writeSfntHeader(byte[] data, int tableCount) {
        putUnsignedInt(data, 0, 0x00010000L);
        putUnsignedShort(data, 4, tableCount);
        putUnsignedShort(data, 6, 0);
        putUnsignedShort(data, 8, 0);
        putUnsignedShort(data, 10, 0);
    }

    private static void writeTableRecord(
            byte[] data,
            int index,
            String tag,
            int offset,
            int length
    ) {
        int position = 12 + index * 16;
        byte[] tagBytes = tag.getBytes(StandardCharsets.ISO_8859_1);
        System.arraycopy(tagBytes, 0, data, position, 4);
        putUnsignedInt(data, position + 4, 0);
        putUnsignedInt(data, position + 8, offset);
        putUnsignedInt(data, position + 12, length);
    }

    private static void putUnsignedShort(byte[] data, int offset, int value) {
        data[offset] = (byte) (value >>> 8);
        data[offset + 1] = (byte) value;
    }

    private static void putUnsignedInt(byte[] data, int offset, long value) {
        data[offset] = (byte) (value >>> 24);
        data[offset + 1] = (byte) (value >>> 16);
        data[offset + 2] = (byte) (value >>> 8);
        data[offset + 3] = (byte) value;
    }
