package org.ofdrw.converter.utils;

import org.junit.jupiter.api.Test;
import org.ofdrw.core.basicType.ST_Array;
import org.ofdrw.core.text.TextCode;
import org.ofdrw.core.text.CT_CGTransform;
import org.ofdrw.converter.point.TextCodePoint;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for PointUtil.calPdfTextCoordinate
 * Focus on observable behaviors described in the specification:
 * - Entity replacement in text
 * - Per-character output count matches number of characters after replacement
 * - DeltaX/DeltaY influence on positions
 * - Optional CTM handling (hasCtm) with identity CTM does not change results
 * - Final glyph assignment via CGTransform
 */
public class PointUtilCalPdfTextCoordinateTests {

    // Helper: create a simple TextCode with given text, optional deltaX/deltaY and coordinates
    private TextCode makeTextCode(String text, Double x, Double y, ST_Array deltaX, ST_Array deltaY) {
        TextCode tc = new TextCode();
        // set content
        tc.setContent(text);
        // coordinates
        tc.setX(x);
        tc.setY(y);
        // deltas
        tc.setDeltaX(deltaX);
        tc.setDeltaY(deltaY);
        return tc;
    }

    // Helper: build a simple CGTransform with glyphs for final glyph assignment
    private CT_CGTransform makeCgTransform(int codePosition, int codeCount, List<String> glyphs) {
        CT_CGTransform cg = new CT_CGTransform();
        cg.setCodePosition(codePosition);
        cg.setCodeCount(codeCount);
        // convert glyphs to ST_Array
        ST_Array arr = new ST_Array(glyphs.toArray(new String[0]));
        cg.setGlyphs(arr);
        return cg;
    }

    @Test
    public void testEntityReplacementAndCharacterCount() {
        // text "A&lt;B" after replacement becomes "A<B" -> 3 characters: 'A','<','B'
        List<TextCode> textCodes = new ArrayList<>();
        // Create a single TextCode with text containing the entity
        TextCode tc = new TextCode();
        tc.setContent("A&lt;B");
        textCodes.add(tc);

        // No delta, no CGTransform
        List<CT_CGTransform> cgTransforms = new ArrayList<>();

        // Call with boundary null, hasCtm false, fixOriginToPdf true to exercise final position
        List<TextCodePoint> results =
                PointUtil.calPdfTextCoordinate(100, 100, null, 12f, textCodes, cgTransforms, null, null, false, null, true, 1.0);

        // Expect 3 points corresponding to 'A', '<', 'B'
        assertEquals(3, results.size(), "Should emit one point per resulting character after entity replacement");

        // Verify the three characters are 'A', '<', 'B' in order
        // Access text through the point's text
        String firstChar = results.get(0).getText();
        String secondChar = results.get(1).getText();
        String thirdChar = results.get(2).getText();

        assertEquals("A", firstChar);
        assertEquals("<", secondChar);
        assertEquals("B", thirdChar);

        // Verify that the second character's x increases relative to the first, due to DeltaX default to 0s
        // In absence of DeltaX, X does not advance; with an entity replacement, at least order is preserved.
        // We expect some non-decreasing x across characters
        double x0 = results.get(0).getX();
        double x1 = results.get(1).getX();
        double x2 = results.get(2).getX();
        assertTrue(x1 >= x0 - 1e-6, "X should not decrease between characters");
        assertTrue(x2 >= x1 - 1e-6, "X should not decrease between characters");
    }

    @Test
    public void testDeltaXInfluencesPositionsWithoutCtm() {
        // Text "AB" with DeltaX [1.0] should advance by about 1 unit for each subsequent char
        List<TextCode> textCodes = new ArrayList<>();
        TextCode tc = new TextCode();
        tc.setContent("AB");
        // No initial X/Y; DeltaX length 1 ensures repetition for second char
        tc.setDeltaX(new ST_Array(1.0f, 1.0f)); // values will be used; second char uses index 0 due to length handling
        textCodes.add(tc);

        List<CT_CGTransform> cgTransforms = new ArrayList<>(); // no CGTransform, so no skip

        List<TextCodePoint> pts = PointUtil.calPdfTextCoordinate(
                200, // width
                200, // height
                null, // boundary
                12f, // fontSize
                textCodes,
                cgTransforms,
                null,
                null,
                false,
                null,
                true,
                1.0);

        // 2 characters expected
        assertEquals(2, pts.size());

        // The second point's X should be greater than the first due to deltaX = 1 repeatedly
        double dx = pts.get(1).getX() - pts.get(0).getX();
        assertTrue(dx > 0, "DeltaX should advance X for the second character");
    }

    @Test
    public void testGlyphAssignmentViaCgTransform() {
        // Prepare two characters and a CGTransform that assigns a glyph to the first character
        List<TextCode> textCodes = new ArrayList<>();
        TextCode tc = new TextCode();
        tc.setContent("AB"); // two characters
        textCodes.add(tc);

        List<CT_CGTransform> cgTransforms = new ArrayList<>();
        // Build glyphs list without using List.of to maintain compatibility with Java 8
        List<String> glyphs = new ArrayList<>();
        glyphs.add("G1");
        cgTransforms.add(makeCgTransform(0, 1, glyphs));

        List<TextCodePoint> pts = PointUtil.calPdfTextCoordinate(
                100, 100, null, 12f, textCodes, cgTransforms, null, null, false, null, true, 1.0);

        // first point's glyph should be "G1" (glyphs are appended for range; here range size equals codeCount)
        assertFalse(pts.isEmpty(), "Result should not be empty");
        assertEquals("G1", pts.get(0).getGlyph(), "First point should receive the glyph from CGTransform");
    }
}

