package org.ofdrw.layout.element.canvas;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class NamedColorRgbTests {

    @Test
    void testNullAndEmptyReturnsNull() {
        assertNull(NamedColor.rgb(null));
        assertNull(NamedColor.rgb(""));
    }

    @Test
    void testWhitespaceThrowsException() {
        // As per specification, non-empty input containing only whitespace may throw unchecked exception after trimming
        assertThrows(RuntimeException.class, () -> NamedColor.rgb("   "));
    }

    @Test
    void testNamedColorCaseInsensitive() {
        int[] rgb = NamedColor.rgb("Blue");
        assertNotNull(rgb);
        assertArrayEquals(new int[]{0, 0, 255}, rgb);
    }

    @Test
    void testThreeDigitHexExpansion() {
        int[] rgb = NamedColor.rgb("#0f0");
        assertNotNull(rgb);
        assertArrayEquals(new int[]{0, 255, 0}, rgb);
    }

    @Test
    void testRgbFunction() {
        int[] rgb = NamedColor.rgb("rgb( 1, 2, 3)");
        assertNotNull(rgb);
        assertArrayEquals(new int[]{1, 2, 3}, rgb);
    }

    @Test
    void testRgbaFunctionAlpha() {
        int[] rgb = NamedColor.rgb("rgba(10,20,30,0.5)");
        assertNotNull(rgb);
        assertArrayEquals(new int[]{10, 20, 30, 127}, rgb);
    }

    @Test
    void testHexDecoding() {
        int[] rgb = NamedColor.rgb("#112233");
        assertNotNull(rgb);
        assertArrayEquals(new int[]{0x11, 0x22, 0x33}, rgb);
    }

    @Test
    void testDecodeFailureReturnsNull() {
        // Not a known color name / rgb(a) form / valid hex
        assertNull(NamedColor.rgb("not-a-color"));
    }
}

