import org.ofdrw.layout.element.Div;

/**
 * Unit tests for DivRender.render to validate rendering behavior against the specification.
 */
public class DivRenderRenderTests {

    @Test
    void testNoBackgroundNoBorderNoRender() {
        // Div with no background and no border should not render anything
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> d = new Div<>(0.0, 0.0, 50.0, 0.0); // height is 0 to keep it minimal but non-null
        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, d, maxUnitID);

        List<?> blocks = layer.getPageBlocks();
        assertTrue(blocks.isEmpty(), "No PathObjects should be added when there is no background and no border.");
        assertEquals(0, maxUnitID.get(), "maxUnitID should not be incremented when nothing is drawn.");
    }

    @Test
    void testBackgroundRendersBackgroundOnly() {
        // Background present: should render exactly two PathObjects (as per implementation behavior)
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> d = new Div<>(0.0, 0.0, 50.0, 30.0);
        d.setBackgroundColor(10, 20, 30); // non-null background
        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, d, maxUnitID);

        List<?> blocks = layer.getPageBlocks();
        assertEquals(2, blocks.size(), "Should render exactly two PathObjects for the background (as per implementation).");
        for (Object b : blocks) {
            assertTrue(b instanceof PathObject, "Rendered object should be a PathObject (background).");
        }
        assertEquals(2, maxUnitID.get(), "maxUnitID should be incremented twice for the two background PathObjects.");
    }

    @Test
    void testUniformBorderRendersSingleBorder() {
        // Uniform border on all sides should render a single border PathObject
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> d = new Div<>(0.0, 0.0, 50.0, 20.0);
        d.setBorder(4.0); // all sides equal
        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, d, maxUnitID);

        List<?> blocks = layer.getPageBlocks();
        assertEquals(1, blocks.size(), "Should render exactly one uniform border PathObject.");
        assertTrue(blocks.get(0) instanceof PathObject, "Rendered object should be a PathObject (border).");
        assertEquals(1, maxUnitID.get(), "maxUnitID should be incremented once for the border.");
    }

    @Test
    void testUnequalBordersRendersFourBorders() {
        // Unequal borders should render four separate PathObjects (top, bottom, left, right)
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> d = new Div<>(0.0, 0.0, 60.0, 20.0);
        d.setBorder(4.0, 6.0, 4.0, 2.0); // top, right, bottom, left
        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, d, maxUnitID);

        List<?> blocks = layer.getPageBlocks();
        assertEquals(4, blocks.size(), "Should render four separate border PathObjects for unequal widths.");
        for (Object b : blocks) {
            assertTrue(b instanceof PathObject, "Each rendered border should be a PathObject.");
        }
        assertEquals(4, maxUnitID.get(), "maxUnitID should be incremented for each created PathObject.");
    }

    @Test
    void testHeightNullThrowsWhenBorderPresent() {
        // If height is null and there is a border, should throw IllegalArgumentException
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> d = new Div<>();
        d.setBorderTop(1.0); // non-zero border but height remains null

        AtomicInteger maxUnitID = new AtomicInteger(0);

        assertThrows(IllegalArgumentException.class, () -> DivRender.render(layer, d, maxUnitID),
                "Should throw IllegalArgumentException when height is null and rendering would occur.");
    }
