public class DivRenderRenderTests {

    /**
     * Test that when there is no background color and no border, render returns
     * early without modifying the layer and without incrementing maxUnitID.
     */
    @Test
    public void testNoBackgroundNoBorderLeavesLayerUnchanged() {
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div<?>> e = new Div<>(0, 0, 0, 0); // minimal div; height may be ignored due to early return
        AtomicInteger maxUnitID = new AtomicInteger(0);

        // invoke
        DivRender.render(layer, e, maxUnitID);

        // expect no objects created
        assertEquals(0, maxUnitID.get(), "maxUnitID should not increment when there is no background and no border");
        // layer should remain empty (no page blocks added)
        assertEquals(0, layer.getPageBlocks().size(), "Layer should not contain any page blocks when nothing is rendered");
    }

    /**
     * Test that a background color along with equal border widths yields exactly
     * two generated objects: one background and one border, and maxUnitID reflects this count.
     */
    @Test
    public void testBackgroundWithEqualBordersCreatesBackgroundAndSingleBorder() {
        CT_PageBlock layer = new CT_PageBlock();
        // Create a div with explicit coordinates to ensure rendering calculations
        Div<Div<?>> e = new Div<>(0, 0, 20.0, 10.0);
        e.setBackgroundColor(255, 0, 0); // red background
        e.setHeight(10.0);
        e.setWidth(20.0);
        // Equal border widths
        e.setBorderTop(2.0);
        e.setBorderRight(2.0);
        e.setBorderBottom(2.0);
        e.setBorderLeft(2.0);

        AtomicInteger maxUnitID = new AtomicInteger(0);

        // invoke
        DivRender.render(layer, e, maxUnitID);

        // expect two objects created: background + single border
        assertEquals(2, maxUnitID.get(), "Expected exactly 2 PathObjects created (background + border)");
        // At least layer should contain some blocks; getPageBlocks() provides a count
        assertTrue(layer.getPageBlocks().size() >= 1, "Layer should contain created page blocks when rendering occurs");
    }

    /**
     * Test that when border widths are unequal, each non-zero side (top, bottom, left, right)
     * is drawn, resulting in four separate border blocks, and maxUnitID reflects this.
     */
    @Test
    public void testUnequalBordersRendersFourSeparateBorders() {
