                .collect(Collectors.toList());
    }

    @Test
    void testRender_NoBackgroundNoBorder_ReturnsWithoutModifyingLayer() {
        CT_PageBlock layer = newLayer();
        Div<?> div = new Div<>(50, 50, 100, 40); // provide position and size, but no background or border
        // Ensure border-less and background-less behavior, with no height requirement
        div.setHeight(null); // not required due to early return
        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, div, maxUnitID);

        // Expect no blocks to be added and maxUnitID unchanged
        assertEquals(0, maxUnitID.get(), "maxUnitID should not be incremented when nothing is rendered.");
        List<PathObject> blocks = getPathObjects(layer);
        assertTrue(blocks.isEmpty(), "Layer should have no PathObject blocks when Div has no background and no border.");
    }

    @Test
    void testRender_BackgroundColorWithVisibleContent_AddsBackgroundBlock() {
        CT_PageBlock layer = newLayer();
        Div<?> div = new Div(10, 20, 100, 50)
                .setBackgroundColor(new int[]{10, 20, 30}) // rgb(10,20,30)
                .setWidth(100.0)
                .setHeight(50.0)
                .setPadding(20.0, 10.0, 20.0, 10.0) // top, right, bottom, left
                .setBorderTop(2.0)
                .setBorderRight(2.0)
                .setBorderBottom(2.0)
                .setBorderLeft(2.0);
        // Optional opacity
        div.setOpacity(0.5);

        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, div, maxUnitID);

        // Background should be rendered (layer contains at least 1 PathObject)
        List<PathObject> blocks = getPathObjects(layer);
        assertFalse(blocks.isEmpty(), "Background block should be rendered when background color is set and height/content exist.");
        // Since we only render a single background block when background exists with uniform border, at least one block should be present
        // The exact count can vary depending on subsequent borders; ensure at least one PathObject present and IDs incremented
        assertTrue(maxUnitID.get() > 0, "maxUnitID should be incremented for created PathObject.");
        assertTrue(blocks.stream().anyMatch(p -> p.getID() != null), "Rendered PathObject(s) should have IDs assigned.");
    }

    @Test
    void testRender_IllegalHeightWhenBackgroundOrBorderPresent_Throws() {
        CT_PageBlock layer = newLayer();
        Div div = new Div(0, 0, 100, 50);
        // set a background color using hex string to ensure there is a background
        // Replace ambiguous hex string with explicit int[] to avoid overload ambiguity
        div.setBackgroundColor(new int[]{255, 0, 0});
