        s.setFontSize(fontSize);
        s.setFont(null);
        return s;
    }

    @Test
    public void testRenderSkipsNullParagraph() {
        TestLayerBlock layer = new TestLayerBlock();
        TestResManager resManager = new TestResManager();
        AtomicInteger maxUnitID = new AtomicInteger(0);

        // call with null paragraph
        ParagraphRender.render(layer, resManager, null, maxUnitID);

        // verify no interactions with layer and no increments to maxUnitID
        assertEquals(0, layer.getTextCount() + layer.getPathCount(), "No blocks should be added when paragraph is null");
        assertEquals(0, maxUnitID.get(), "maxUnitID should remain unchanged when nothing is rendered");
    }

    @Test
    public void testRenderWithEmptyLinesTriggersPreparationButSkipsEmptyAfterPrepare() {
        // Paragraph that, upon prepare, contains a single empty line
        EmptyLinesParagraph p = new EmptyLinesParagraph();

        TestLayerBlock layer = new TestLayerBlock();
        TestResManager resManager = new TestResManager();
        AtomicInteger maxUnitID = new AtomicInteger(0);

        ParagraphRender.render(layer, resManager, p, maxUnitID);

        // Since the only line has no inline spans, nothing should be rendered
        assertEquals(0, layer.getTextCount() + layer.getPathCount(), "No TextObjects should be created when there is no content to render");
        assertEquals(0, maxUnitID.get(), "maxUnitID should remain unchanged when nothing is rendered");
    }

    @Test
    public void testRenderSingleLineWithOneSpanCreatesTextObjectAndUpdatesPosition() throws IOException {
        // Build a concrete Paragraph with a single line, a single Span with text
        Paragraph p = new Paragraph(200.0, 50.0); // width 200, height 50
        p.setLineSpace(2.0);
        p.setTextAlign(null); // default left

        // Build a Span with text using the real Span class
        Span span = new Span("Hello");
        span.setFontSize(12.0);
        span.setFont(null); // rely on default font
        span.setColor(new int[]{0, 0, 0});
        span.setWeight(null);
        span.setBold(false);
        // add to paragraph
        p.add(span);

        // create a line that contains the span
        TxtLineBlock line = new TxtLineBlock(150.0, 2.0, TextAlign.left);
        line.getInlineSpans().add(span);
        // attach line to paragraph
        p.getLines().add(line);

