        assertTrue(layer.getTextCount() > 0, "A TextObject should be created and added to the layer");
        assertTrue(maxUnitID.get() > 0, "maxUnitID should be incremented for each rendered text object");
    }

    @Test
    public void testRenderSkipsIfContainerHeightExceeded() {
        // Paragraph with height smaller than the line height to force skip due to overflow
        Paragraph p = new Paragraph(100.0, 5.0);
        TallLineFake line = new TallLineFake(90.0, 4.0, TextAlign.left);
        Span s = spanFrom("ABCD", 10.0);
