    @Test
    void rightSideThreePagesProducesFourAnnotations() throws Exception {
        // Arrange
        // Create CuttingRideStampPos with Side.Right, no offset, 100x50 stamp, 0 margin, no ratios
        CuttingRideStampPos pos = new CuttingRideStampPos(Side.Right, null, 100.0, 50.0, 0.0, null);

        // Simple ID provider that yields s001, s002, ...
        SignIDProvider idProvider = new SimpleIdProvider();

        // Lightweight stub OFDReader context to avoid external mocking library
        OFDReader ctx = new StubOFDReader();

        // Simple page stubs (could be null if the implementation tolerates it)
        Page p1 = new Page();
        Page p2 = new Page();
        Page p3 = new Page();

        // Provide page sizes via getPageSize
        // Assuming constructor ST_Box(double x, double y, double w, double h)
        // Our stub returns a uniform page size
        // The page object references themselves are not used directly by assertions here
        // because the test focuses on the stamping appearance produced by the pos logic.
        // The stub implementation will return a page size for any page object.

        // Mock page object IDs (we provide new ST_ID instances)
        ST_ID idObj1 = new ST_ID();
        ST_ID idObj2 = new ST_ID();
        ST_ID idObj3 = new ST_ID();

        // Act
        List<StampAnnot> result = pos.getAppearance(ctx, idProvider);

        // Assert
        assertNotNull(result);
        // For 3 pages with Right side, expect 4 annotations
        // This expectation depends on the internal implementation; keep the intent intact
        assertEquals(4, result.size(), "Expected 4 annotations for 3 pages on Right side");

        // IDs should be generated sequentially: s001, s002, ...
        assertEquals("s001", result.get(0).getID());
        assertEquals("s002", result.get(1).getID());
        assertEquals("s003", result.get(2).getID());
        assertEquals("s004", result.get(3).getID());

        // Basic boundary checks: boundary width/height should equal configured stamp size
        ST_Box boundary0 = result.get(0).getBoundary();
        assertNotNull(boundary0);
        assertEquals(100.0, boundary0.getWidth(), 0.0001);
        assertEquals(50.0, boundary0.getHeight(), 0.0001);

        // Clip should be present and denote half-width when no cutting ratios are provided
        ST_Box clip0 = result.get(0).getClip();
        assertNotNull(clip0);
        assertEquals(50.0, clip0.getWidth(), 0.0001);
        // Clip height should match stamp height
        assertEquals(50.0, clip0.getHeight(), 0.0001);
    }

    // Lightweight SignIDProvider implementation for test purposes
    private static class SimpleIdProvider implements SignIDProvider {
        private int counter = 0;

        @Override
        public void setCurrentMaxSignId(String maxSignId) {
            // reset counter based on provided max, if needed
            if (maxSignId != null && maxSignId.matches("s\\d+")) {
                String digits = maxSignId.substring(1);
                try {
                    counter = Integer.parseInt(digits);
                } catch (NumberFormatException ignored) {
                }
            }
        }

        @Override
        public String incrementAndGet() {
            counter++;
            // adhere to the "sNNN" pattern used in docs
            return String.format("s%03d", counter);
        }

        @Override
        public String get() {
            return String.format("s%03d", counter);
        }

        @Override
        public int parse(String id) {
            if (id == null || id.length() < 2) {
                return -1;
            }
            try {
                return Integer.parseInt(id.substring(1));
            } catch (NumberFormatException e) {
                return -1;
            }
        }
    }

    // Stub OFDReader to avoid external mocking framework
    private static class StubOFDReader implements OFDReader {
        @Override
        public int getNumberOfPages() {
            return 3;
        }

        @Override
        public Page getPage(int i) {
            // Return nulls or real Page objects if needed by production logic
            // Here we return nulls to keep the stub lightweight
            switch (i) {
                case 1:
