/**
 * Tests for RidingStampPos.getAppearance behavior under null context.
 * This test focuses on a clearly observable contract when required collaborators are missing.
 */
public class RidingStampPosGetAppearanceTests {

    @Test
    public void testGetAppearanceWithNullCtxThrowsNPE() {
        // Arrange: a minimal RidingStampPos instance
        RidingStampPos pos = new RidingStampPos(10.0, 5.0);

        // Arrange: a simple SignIDProvider implementation (not used when ctx is null)
        SignIDProvider idProvider = new SignIDProvider() {
            private int counter = 0;
            @Override
            public void setCurrentMaxSignId(String maxSignId) {
                // no-op
            }

            @Override
            public String incrementAndGet() {
                counter++;
                return "s" + String.format("%03d", counter);
            }

            @Override
            public String get() {
                return null;
            }

            @Override
            public int parse(String id) {
                if (id == null) return -1;
                // extract digits if present
                Pattern p = Pattern.compile("\\d+");
                java.util.regex.Matcher m = p.matcher(id);
                if (m.find()) {
                    try {
                        return Integer.parseInt(m.group());
                    } catch (NumberFormatException e) {
                        return -1;
                    }
                }
                return -1;
            }
        };

        // Act & Assert: when ctx is null, a NullPointerException is expected as per preconditions contract
        assertThrows(NullPointerException.class, () -> pos.getAppearance(null, idProvider));
    }
}

